const $ = (q) => document.querySelector(q);
const escapeHTML = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
const labels = {opportunity:'기회 우세', mixed:'기회·위기 혼재', risk:'위기 우세', insufficient:'판단 보류'};
const symbols = {opportunity:'●', mixed:'◐', risk:'▲', insufficient:'○'};
let sourceCatalog = [], dataSources = [];
let readinessState = {counts:{},sources:[]}, refreshState = {jobs:[],settings:{enabled:false,version:0},tasks:{}};
let evidenceFilter = {status:'all',topic:'all',query:''};
let records = [], selectedVersion = null, editing = null;
const latest = (kind, id) => records.filter(r => r.kind === kind && (!id || r.id === id)).sort((a,b)=>b.version-a.version)[0];
const analyses = () => records.filter(r=>r.kind==='analysis').sort((a,b)=>a.version-b.version);
const analysis = () => analyses().find(a=>a.version === selectedVersion) || latest('analysis','ai-demand');
const policies = () => [...new Set(records.filter(r=>r.kind==='policy').map(r=>r.id))].map(id=>latest('policy',id));
const portfolio = () => latest('portfolio','personal');
const badge = s => `<span class="signal ${e(s)}">${symbols[s]} ${labels[s]}</span>`;
const stamp = s => new Date(s).toLocaleString('ko-KR', {timeZone:'Asia/Seoul'});
const heading = (eyebrow, title, description, extra='') => `<div class="page-title"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${description}</p></div>${extra}</div>`;
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('show'); setTimeout(()=>$('#toast').classList.remove('show'),4000); }
async function load() { const res=await fetch('/api/state'); if(!res.ok) throw Error('기록을 불러오지 못했습니다.'); const state=await res.json();records=state.records;$('.mode').textContent=state.usage_mode==='practice'?'연습 모드 · 개인 기록과 분리':'개인 모드 · 원문 검토 필요'; const catalog=await fetch('/api/collection-sources'); if(!catalog.ok) throw Error('출처 목록을 불러오지 못했습니다.'); sourceCatalog=(await catalog.json()).sources; const api=await fetch('/api/data-sources'); if(!api.ok) throw Error('API 출처 목록을 불러오지 못했습니다.');dataSources=(await api.json()).sources; const reviewRes=await fetch('/api/workbench');if(!reviewRes.ok)throw Error('확인 목록을 불러오지 못했습니다.');workbench=await reviewRes.json(); const extra=await Promise.all([fetch('/api/readiness'),fetch('/api/refresh')]); if(extra.some(r=>!r.ok))throw Error('자료 준비 상태를 불러오지 못했습니다.'); [readinessState,refreshState]=await Promise.all(extra.map(r=>r.json())); }
async function post(url, payload) { const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); const data=await res.json(); if(!res.ok) throw Error(data.error); await load(); return data; }
function card(a, full=false) {
 return `<article class="analysis-card"><div class="row"><span class="eyebrow">QUESTION / 가상 분석 v${a.version}</span>${badge(a.signal)}</div><h2>${e(a.question)}</h2><p class="answer">${e(a.answer)}</p>${full?`<div class="two-col evidence"><div><span class="positive">＋ 기회 근거</span><p>${e(a.opportunity)}</p></div><div><span class="negative">− 위기 근거</span><p>${e(a.risk)}</p></div></div>`:''}<div class="next"><span>다음 확인 조건</span><strong>${e(a.next_condition)}</strong></div><div class="meta">자료 기준 ${e(a.basis_at)} · 실제 저장 ${e(stamp(a.recorded_at))}<br>시연 규칙 ${e(a.rule_version)} · AI 자동 생성 아님</div>${full?`<details><summary>근거 자료와 신호 변경 이유</summary><p>${e(a.reason)}</p>${a.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.label)} ↗</a><p class="meta">가상 공개일 ${e(s.published_at)} · 출처 유형: 시연</p>`).join('')}</details>`:`<a class="text-link" href="#policy/p-ai">타임라인과 근거 살펴보기 ↗</a>`}</article>`;
}
function home() {
 const a=analysis(), p=portfolio(), total=p.holdings.reduce((s,h)=>s+h.amount,0), semi=p.holdings.filter(h=>h.semiconductor).reduce((s,h)=>s+h.amount,0)/total*100;
 return attentionSummary()+manualSummary()+heading('YOUR WEEK, IN CONTEXT', '흐름을 읽고, 근거를 남기다.', '정책의 변화가 산업과 내 자산에 닿는 과정을 살펴보세요.', '<a class="button primary" href="#review">주말 질문 정리 ↗</a>')+
 `<div class="stats"><div><span>등록된 가상 정책</span><strong>03 <small>개</small></strong><p>AI 인프라 · 반도체 · 전력</p></div><div><span>분석 이력</span><strong>02 <small>버전</small></strong><p>판단 보류 → 기회·위기 혼재 · 시연</p></div><div><span>내 반도체 비중</span><strong>${semi.toFixed(1)}<small>%</small></strong><p>사용자 입력 상대 금액 기준</p></div></div>
 <div class="section-label"><h2>이번 사례의 핵심 변화</h2><span>시연 자료 · 실제 시장 요약 아님</span></div><div class="two-col main-grid"><div>${card(a)}<div class="path-card"><span class="eyebrow">FOLLOW THE CONNECTION</span><h3>정책에서 기업까지</h3><div class="flow"><a href="#policy/p-ai">공공 투자</a><span>→</span><a href="#map">AI 인프라</a><span>⇢</span><a href="#stock/nvda">관심 기업</a></div><p class="meta">점선 관계: 공급 가능성 예시 · 계약 미확인</p></div></div><aside class="panel"><div class="row"><h2>다음에 확인할 것</h2><span class="counter">03</span></div>${['지원 대상이 선정됐는가?','장비 구매 계약이 공개됐는가?','공급사의 실적에 반영됐는가?'].map((x,i)=>`<a class="check-item" href="#policy/p-ai"><span>0${i+1}</span><div><strong>${x}</strong><small>일정 미확정 · 가상 관찰 조건</small></div><b>↗</b></a>`).join('')}<div class="quiet"><h3>이번 주 나의 질문</h3><p>정책의 진전과 종목의 기회를 같은 것으로 보고 있지는 않을까?</p><a href="#notes" class="text-link">내 판단 기록하기 →</a></div></aside></div>`;
}
function mapView() {
 return heading('POLICY LANDSCAPE','정책·산업 지도','국가 전체의 통계가 아닌, 등록한 정책의 실행 단계입니다. 실제 출처는 사용자 검토 완료 후 표시됩니다.')+`<div class="filters"><label>국가 <select id="country"><option value="all">전체</option>${[...new Set(policies().map(p=>p.country))].map(x=>`<option>${e(x)}</option>`).join('')}</select></label><label>산업 <select id="sector"><option value="all">전체</option>${[...new Set(policies().map(p=>p.sector))].map(x=>`<option>${e(x)}</option>`).join('')}</select></label></div><div class="panel table-wrap"><table><thead><tr><th>국가</th><th>정책 · 자료 유형</th><th>산업</th><th>단계</th><th>지원 규모</th></tr></thead><tbody id="policy-rows"></tbody></table></div><div class="quiet"><h3>비교할 때 확인하세요</h3><p>예산, 보증 한도, 민간 투자 목표와 실제 지급액은 서로 다른 금액입니다. 이 시제품에는 투자액을 임의로 설정하지 않았습니다.</p></div>`;
}
function drawPolicyRows() {
 const rows=policies().filter(p=>p.demo||p.review_status==='reviewed').filter(p=>($('#country').value==='all'||p.country===$('#country').value)&&($('#sector').value==='all'||p.sector===$('#sector').value));
 $('#policy-rows').innerHTML=rows.length?rows.map(p=>`<tr><td>${e(p.country)}</td><td><a href="#policy/${e(p.id)}">${e(p.title)} ↗</a><br><small>${p.demo?'가상 사례':'수동 등록 · 사용자 검토 완료'}</small></td><td>${e(p.sector)}</td><td><span class="pill">${policyStages[p.stage]}</span></td><td>${e(p.amount)}</td></tr>`).join(''):'<tr><td colspan="5">이 조건에 표시할 정책이 없습니다. 검토 대기 자료는 출처 관리에서 확인하세요.</td></tr>';
}
function policyView(id) {
 const p=latest('policy',id); if(!p) return '<h1>등록되지 않은 정책입니다.</h1>';
 if(!p.demo) return manualPolicy(p)+`<div class="section-label"><h2>기업 연결과 근거</h2><a class="button" href="#relations">연결 관리 →</a></div>`+relationCards(relations().filter(r=>r.policy_id===id));
 return heading('POLICY / '+e(p.country),e(p.title),'가상 정책 · 계획과 실제 집행을 분리해 확인합니다.')+`<div class="two-col main-grid"><div class="panel"><div class="row"><h2>실행 타임라인</h2><span class="pill">${e(p.scope)}</span></div><ol class="timeline">${p.events.map(x=>`<li><span class="date">${e(x.date)}</span><h3>${e(x.label)}</h3><p>${e(x.detail)}</p><small>가상 공개일 ${e(x.published_at)}</small></li>`).join('')}<li class="pending"><span class="date">다음 확인</span><h3>계약 · 집행 · 가동</h3><p>아직 자료가 없습니다. 진행률을 추정하지 않습니다.</p></li></ol><a class="text-link" href="/demo-source" target="_blank" rel="noopener">시연 원문 설명서 ↗</a></div><div>${p.id==='p-ai'?card(analysis(),true):`<article class="analysis-card">${badge('insufficient')}<h2>이 정책이 실제 수요로 이어지는가?</h2><p>가상 단계 이외의 집행 자료가 없습니다.</p><div class="next"><span>다음 확인 조건</span><strong>계약과 지급 내역 확인</strong></div></article>`}</div></div><div class="section-label"><h2>산업과 기업 연결</h2><span>공급 가능성 예시 · 계약 미확인</span></div><div class="company-grid">${[['nvda','엔비디아','연산'],['mu','마이크론','메모리'],['mrvl','마벨','네트워크']].map(([id,name,role])=>`<a class="company" href="#stock/${id}"><small>${role}</small><h3>${name} ↗</h3><p>정책 수요와의 관계를 조사할 후보</p></a>`).join('')}</div>`;
}
