function portfolioView() {
 const p=portfolio(), sum=p.holdings.reduce((s,h)=>s+h.amount,0);
 return heading('MY EXPOSURE','내 자산과 공통 위험','대화에서 입력한 상대 금액입니다. 수익률·취득 원가는 계산하지 않습니다.')+
 `<div class="two-col main-grid"><section class="panel"><h2>자산 구성</h2><form id="portfolio-form"><div class="holdings">${p.holdings.map(h=>`<div class="holding"><div><label for="asset-${h.id}">${e(h.name)}</label><span>${(h.amount/sum*100).toFixed(1)}%</span></div><div class="bar"><i style="width:${h.amount/sum*100}%"></i></div><input id="asset-${h.id}" name="${h.id}" type="number" min="0" max="1000000000" step="any" value="${h.amount}" required aria-label="${e(h.name)} 상대 금액"></div>`).join('')}</div><button class="primary" type="submit">새 자산 기록 저장</button><p class="meta">v${p.version} · ${e(stamp(p.recorded_at))}<br>${e(p.source)}</p></form></section><section><div class="panel"><p class="eyebrow">SCENARIO / 예측 아님</p><h2>반도체가 함께 움직인다면</h2><label for="shock">반도체 묶음 변동 가정 <strong id="shock-label">−15%</strong></label><input type="range" id="shock" min="-40" max="20" value="-15"><div class="big-number" id="impact"></div><p>전체 자산 변동 시나리오</p><div class="next"><span>가정</span><strong>나머지 자산 가격과 환율은 그대로</strong></div><p class="meta">엔비디아·마이크론·SK하이닉스·마벨을 묶었습니다. 현재 저장된 비중을 사용합니다. −10% 기준의 자동 경보는 아직 적용하지 않습니다.</p></div><div class="quiet"><h3>질문 · 자산 집중도가 달라졌나?</h3><p>금액을 수정하고 저장하면 비중과 시나리오를 다시 계산합니다.</p>${badge('insufficient')}<p>위험 허용 범위의 기준이 미확정입니다.</p><p><strong>다음 확인:</strong> 손실 기준일과 기준 통화 결정</p></div><details class="panel"><summary>자산 기록 이력</summary>${records.filter(r=>r.kind==='portfolio').map(r=>`<p>v${r.version} · ${e(stamp(r.recorded_at))}<br><small>${r.holdings.map(h=>`${e(h.name)} ${h.amount}`).join(' / ')}</small></p>`).join('')}</details></section></div>`;
}
function updateImpact() { const p=portfolio(), sum=p.holdings.reduce((s,h)=>s+h.amount,0), semi=p.holdings.filter(h=>h.semiconductor).reduce((s,h)=>s+h.amount,0); const shock=Number($('#shock').value); $('#shock-label').textContent=`${shock}%`; $('#impact').textContent=`${(shock*semi/sum).toFixed(2)}%`; }
function notesView() {
 const notes=records.filter(r=>r.kind==='note'), current=[...new Set(notes.map(n=>n.id))].map(id=>latest('note',id));
 return heading('WEEKEND REVIEW','질문하고, 판단을 남기다.','이전 기록을 지우지 않고 새 버전으로 저장합니다. AI 답변 기능은 아직 연결하지 않았습니다.', '<a class="button" id="export" href="/api/export" download="research-records.json">기록 JSON 내보내기 ↓</a>')+
 `<div class="two-col main-grid"><section class="panel"><div class="row"><h2>${editing?'판단 업데이트':'새 질문 기록'}</h2><span class="pill">사용자 직접 작성</span></div><form id="note-form"><label>질문<textarea name="question" required maxlength="5000" placeholder="예산 확대가 실제 발주로 이어질까?">${e(editing?.question||'')}</textarea></label><label>내 답변·근거<textarea name="answer" required maxlength="5000" placeholder="현재 확인한 점과 아직 모르는 점">${e(editing?.answer||'')}</textarea></label><label>나의 신호<select name="signal">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===(editing?.signal||'insufficient')?'selected':''}>${v}</option>`).join('')}</select></label><label>다음 확인 조건<textarea name="next_condition" required maxlength="5000" placeholder="확인할 발표·지표·조건">${e(editing?.next_condition||'')}</textarea></label><label>판단 이유 / 변경 이유<input name="reason" required maxlength="5000" value="${e(editing?.reason||'')}" placeholder="어떤 근거 때문에 이렇게 판단했나요?"></label><p class="meta">연결: 가상 산업 분석 v${analysis().version} · 종목의 공식 분석 신호와 별개</p><button class="primary" type="submit">${editing?'새 버전으로 저장':'질문 기록 저장'}</button>${editing?'<button type="button" id="cancel-edit">새 기록 작성으로 돌아가기</button>':''}</form></section><section><div class="section-label"><h2>나의 기록</h2><span>${current.length}개 질문 · ${notes.length}개 버전</span></div>${current.length?current.map(n=>`<article class="panel note"><div class="row"><small>사용자 판단 · v${n.version}</small>${badge(n.signal)}</div><h3>${e(n.question)}</h3><p class="prewrap">${e(n.answer)}</p><div class="next"><span>다음 확인 조건</span><strong>${e(n.next_condition)}</strong></div><p class="meta">${e(stamp(n.recorded_at))} · 가상 분석 v${n.analysis_version} 참조</p><button data-edit="${e(n.id)}">판단 업데이트</button><details><summary>이전 판단과 변경 이유</summary>${notes.filter(x=>x.id===n.id).map(x=>`<div class="history"><strong>v${x.version} · ${labels[x.signal]}</strong><p>${e(x.answer)}</p><p>다음 조건: ${e(x.next_condition)}</p><small>이유: ${e(x.reason)} · ${e(stamp(x.recorded_at))}</small></div>`).join('')}</details></article>`).join(''):'<div class="empty"><span>▤</span><h3>첫 번째 질문을 남겨보세요.</h3><p>오늘의 생각이 다음 주 복기의 기준이 됩니다.</p></div>'}</section></div>`;
}
function render() {
 const [rawRoute, id] = location.hash.slice(1).split('/');
 const route = rawRoute || 'home';
 $('#breadcrumb').textContent=({start:'START / CHECK',home:'OVERVIEW',map:'POLICY MAP',policy:'POLICY TRACKER',stock:'COMPANY',portfolio:'PORTFOLIO',notes:'REVIEW',sources:'SOURCE DESK',relations:'CONNECTIONS',collection:'COLLECTION LOG',evidence:'EVIDENCE REVIEW',review:'DAILY / WEEKEND',history:'APP HISTORY'})[route]||'OVERVIEW';
 document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash.split('/')[0]===`#${route}`));
 let html=({start:startView,home:home,map:mapView,policy:()=>policyView(id),stock:()=>stockView(id)+(id==='nvda'?filingsPanel(id):'')+`<div class="section-label"><h2>등록된 정책 연결</h2><a class="button" href="#relations">관계 관리 →</a></div>`+relationCards(relations().filter(r=>r.company_id===id))+`<div class="section-label"><h2>정책 실행·기업 근거 추적</h2></div>`+progressCards(progressRecords().filter(r=>r.company_id===id)),portfolio:portfolioView,notes:notesView,sources:sourcesView,relations:()=>relationsView()+progressPanel(),collection:()=>refreshPanel()+collectionView()+structuredPanel(),evidence:()=>evidenceView(id),review:reviewView,history:historyView}[route]||home)();
 if(['home','stock'].includes(route)||(route==='policy'&&latest('policy',id)?.demo)) html=`<div class="version-control"></div>`+html;
 $('#view').innerHTML=html;
 const versionControl=$('.version-control');
 if(versionControl) { versionControl.innerHTML=`<label for="analysis-version">가상 산업 분석 이력</label><select id="analysis-version">${analyses().map(a=>`<option value="${a.version}" ${a.version===analysis().version?'selected':''}>v${a.version} · ${e(a.basis_at)} · ${labels[a.signal]}</option>`).join('')}</select><small>당시 실제 판단이 아닌, 시제품에서 만든 예시 이력</small>`; $('#analysis-version').onchange=ev=>{selectedVersion=Number(ev.target.value);render();}; }
 if(route==='start') bindOperations();
 if(route==='map') {drawPolicyRows();$('#country').onchange=drawPolicyRows;$('#sector').onchange=drawPolicyRows;}
 if(route==='sources') bindSources();
 if(route==='relations'){bindRelations();bindProgress();}
 if(route==='collection') bindCollection();
 if(route==='evidence') bindEvidence();
 if(route==='review') bindReview();
 if(route==='history') bindHistory();
 if(route==='portfolio') {
 updateImpact();$('#shock').oninput=updateImpact;
 const version=portfolio().version;
 $('#portfolio-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.submitter;button.disabled=true;try{const amounts=Object.fromEntries([...new FormData(ev.target)].map(([k,v])=>[k,Number(v)]));await post('/api/portfolio',{amounts,expected_version:version});render();toast('새 자산 기록을 저장했습니다.');}catch(err){toast(err.message);button.disabled=false;}};
 }
 if(route==='notes') {
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{editing=latest('note',b.dataset.edit);render();$('#note-form textarea').focus();});
 if($('#cancel-edit'))$('#cancel-edit').onclick=()=>{editing=null;render();};
 $('#note-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.submitter;button.disabled=true;try {const data=Object.fromEntries(new FormData(ev.target));await post('/api/notes',{...data,id:editing?.id,expected_version:editing?.version||0,analysis_version:analysis().version});editing=null;render();toast('판단과 다음 확인 조건을 저장했습니다.');}catch(err){toast(err.message);button.disabled=false;}};
 }
}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
load().then(render).catch(err=>{$('#view').innerHTML=`<div class="empty"><h1>기록을 불러오지 못했습니다.</h1><p>${e(err.message)}</p><button id="retry">다시 시도</button></div>`;$('#retry').onclick=()=>location.reload();});

const policyStages = ['계획 발표','예산 확정','지원 공고','계약','집행','가동','지연','축소','취소'];
const reviewLabels = {draft:'검토 대기',reviewed:'사용자 검토 완료',returned:'보완 필요'};
let policyEditing = null;
function manualPolicy(p) {
 const history=records.filter(r=>r.kind==='policy'&&r.id===p.id);
 return heading('POLICY / MANUAL SOURCE',e(p.title),`${e(p.country)} · ${e(p.sector)} · ${reviewLabels[p.review_status]} · 자동 검증 아님`, '<a class="button" href="#sources">출처·검토 관리 →</a>')+
 `<div class="two-col main-grid"><section class="panel"><h2>출처와 실행 단계</h2><span class="pill">${e(policyStages[p.stage])}</span><p class="meta">사건일 ${e(p.event_date||'미상')} · 원문 공개일 ${e(p.published_date||'미상')}<br>시스템 기록 ${e(stamp(p.recorded_at))}</p><h3>${e(p.publisher)}</h3><a class="text-link" href="${e(p.source_url)}" target="_blank" rel="noopener noreferrer">등록한 원문 열기 ↗</a><blockquote class="prewrap">${e(p.excerpt)}</blockquote><p class="meta">${p.source_document_id?'수신 자료에 연결한 발췌 · 원문과 변경 여부 대조 필요':'사용자 입력 발췌 · 시스템 원문 수집 미수행'}</p><details><summary>단계·출처·검토 변경 이력 (${history.length})</summary>${history.map(v=>`<div class="history"><strong>v${v.version} · ${reviewLabels[v.review_status]} · ${policyStages[v.stage]}</strong><p>${e(v.reason)}</p><p>${e(v.answer)}</p><p class="meta">${e(stamp(v.recorded_at))} · 공개일 ${e(v.published_date||'미상')}</p><a href="${e(v.source_url)}" target="_blank" rel="noopener noreferrer">당시 출처 ↗</a><p class="prewrap">${e(v.excerpt)}</p></div>`).join('')}</details></section><article class="analysis-card"><div class="row"><span class="eyebrow">사용자 작성 · v${p.version}</span>${badge('insufficient')}</div><h2>${e(p.question)}</h2><p class="answer prewrap">${e(p.answer)}</p><p class="meta">${e(p.uncertainty)}</p><div class="next"><span>다음 확인 조건</span><strong>${e(p.next_condition)}</strong></div><p>원문 검토 완료는 종목의 기회 신호가 아닙니다. 기업별 연결 근거는 아래에서 별도로 확인합니다.</p></article></div>`;
}
function sourcesView() {
 const p=policyEditing;
 const field=(name,label,type='text',required=true)=>`<label>${label}<input name="${name}" type="${type}" ${required?'required':''} maxlength="${name==='source_url'?2048:500}" value="${e(p?.[name]||'')}"></label>`;
 const area=(name,label)=>`<label>${label}<textarea name="${name}" required maxlength="5000">${e(p?.[name]||'')}</textarea></label>`;
 const manual=policies().filter(x=>!x.demo);
 return heading('SOURCE DESK','정책·출처 등록과 검토','수동 등록은 자동 수집과 다릅니다. 원문을 대조한 뒤 정책 지도에 반영합니다.')+
 `<div class="notice">연결 상태 <span>사용자가 정상 동작을 확인한 사이트 3곳입니다. 초기 요청의 프록시 차단 기록은 보존합니다. 현재 접근 여부와 수신 자료는 수집 상태 화면에서 확인하세요.</span></div>${officialSourceExamples()}<div class="two-col main-grid" style="margin-top:24px"><section class="panel"><h2>${p?'정책 새 버전 작성':'새 정책 등록'}</h2><form id="policy-form">${field('title','정책 이름')}${field('country','국가')}${field('sector','산업')}${field('publisher','발표 기관')}${field('source_url','출처 HTTPS URL','url')}<div class="two-col">${field('event_date','사건일 · 미상이면 비움','date',false)}${field('published_date','원문 공개일 · 미상이면 비움','date',false)}</div><label>정책 실행 단계<select name="stage">${policyStages.map((x,i)=>`<option value="${i}" ${i===p?.stage?'selected':''}>${x}</option>`).join('')}</select></label>${area('excerpt','근거 발췌 · 필요한 부분만 입력')}${area('question','질문')}${area('answer','내 답변 · 확인한 사실과 불확실성')}${area('next_condition','다음 확인 조건')}${field('reason','등록·변경 이유')}<p class="meta">저장하면 검토 대기 상태가 됩니다. 자동으로 종목 신호를 생성하지 않습니다.</p><button class="primary" type="submit">검토 대기로 저장</button>${p?'<button type="button" id="policy-new">새 정책 작성</button>':''}</form></section><section><div class="section-label"><h2>등록 자료</h2><span>${manual.length}개 정책</span></div>${manual.length?manual.map(x=>`<article class="panel note"><div class="row"><span class="pill">${reviewLabels[x.review_status]}</span><small>v${x.version}</small></div><h3><a href="#policy/${e(x.id)}">${e(x.title)} ↗</a></h3><p>${e(x.publisher)} · ${e(policyStages[x.stage])}</p><a class="text-link" href="${e(x.source_url)}" target="_blank" rel="noopener noreferrer">원문 확인 ↗</a><p class="prewrap">${e(x.excerpt)}</p><button data-policy-edit="${e(x.id)}">수정·새 버전</button>${x.review_status==='draft'?`<form class="review-form" data-id="${e(x.id)}" data-version="${x.version}"><label>검토 의견<input name="reason" required maxlength="5000" placeholder="발표 기관·단계·날짜를 대조한 결과"></label><label class="review-check"><input type="checkbox" name="source_checked"> 원문을 열어 발췌·날짜·단계를 대조했습니다</label><button type="submit" name="action" value="approve">검토 완료·지도 반영</button><button type="submit" name="action" value="return">보완 요청</button></form>`:`<p class="meta">검토 기록: ${e(x.reason)}</p>`}</article>`).join(''):'<div class="empty"><h3>아직 등록한 실제 출처가 없습니다.</h3><p>출처 링크만 등록해도 자동 검증된 것으로 표시하지 않습니다.</p></div>'}</section></div>`;
}
function bindSources() {
 document.querySelectorAll('[data-policy-edit]').forEach(b=>b.onclick=()=>{policyEditing=latest('policy',b.dataset.policyEdit);render();$('#policy-form input').focus();});
 if($('#policy-new'))$('#policy-new').onclick=()=>{policyEditing=null;render();};
 const editingSnapshot=policyEditing;
 $('#policy-form').onsubmit=async ev=>{ev.preventDefault(); const b=ev.submitter;b.disabled=true;try{const d=Object.fromEntries(new FormData(ev.target));await post('/api/policies',{...d,action:'save',stage:Number(d.stage),id:editingSnapshot?.id,expected_version:editingSnapshot?.version||0,source_document_id:editingSnapshot?.source_document_id});policyEditing=null;render();toast('검토 대기로 저장했습니다.');}catch(err){toast(err.message);b.disabled=false;}};
 document.querySelectorAll('.review-form').forEach(form=>form.onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;const d=Object.fromEntries(new FormData(form));if(b.value==='approve'&&!d.source_checked){toast('원문 대조 확인이 필요합니다.');return;}b.disabled=true;try{await post('/api/policies',{action:b.value,id:form.dataset.id,expected_version:Number(form.dataset.version),reason:d.reason,source_checked:!!d.source_checked});render();toast(b.value==='approve'?'사용자 검토 완료로 기록했습니다.':'보완 요청을 기록했습니다.');}catch(err){toast(err.message);b.disabled=false;}});
}

function manualSummary() {
 const data=policies().filter(p=>!p.demo);
 return `<div class="quiet"><div class="row"><h3>실제 출처 작업함</h3><a class="text-link" href="#sources">등록·검토 →</a></div><p>사용자 검토 완료 ${data.filter(p=>p.review_status==='reviewed').length}건 · 검토 대기 ${data.filter(p=>p.review_status==='draft').length}건 · 보완 필요 ${data.filter(p=>p.review_status==='returned').length}건</p>${data.filter(p=>p.review_status==='reviewed').map(p=>`<a class="button" href="#policy/${e(p.id)}">${e(p.title)} ↗</a>`).join('')}</div>`;
}

function officialSourceExamples() {
 const sources=[
  ['USAspending','https://www.usaspending.gov/','미국 연방 지원·계약·수혜자 지출 자료','약정 금액과 실제 지급액은 각각 얼마인가?'],
  ['한국 산업부','https://www.motir.go.kr/','산업 정책·지원 사업 공고·보도자료','공고의 지원 조건과 후속 선정 결과는 무엇인가?'],
  ['미국 SEC · EDGAR','https://www.sec.gov/edgar/search/','기업 공시·실적·13F 기관 보유 내역','정부 지원이 기업 공시에서 어떻게 확인되는가?']
 ];
 return `<section class="panel official-sources" aria-label="공식 사이트 사례"><h2>공식 사이트 사례</h2><p class="meta">자료를 찾는 출발점입니다. 아래 기관 링크 자체가 개별 정책의 근거는 아닙니다. 등록 시에는 해당 발표·공고·공시의 상세 URL을 사용하세요.</p><div class="two-col">${sources.map(([name,url,material,question])=>`<article><a class="text-link" href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a><p>${material}</p><small>살펴볼 질문 · ${question}</small><p class="meta">사용자 확인: 정상 동작 · 2026-10-17<br>초기 수집 환경: 프록시 403 · 2026-10-17<br>최신 수집 결과는 수집 상태 화면에서 확인</p></article>`).join('')}</div><p class="meta">CHIPS 기존 상세 주소는 페이지가 없다는 사용자 확인에 따라 목록에서 제외했습니다. 대체 주소는 아직 확인하지 않았습니다.</p></section>`;
}

const relationLabels = {potential:'공급 가능성',confirmed:'계약 확인 · 사용자 대조',indirect:'간접 영향',adverse:'부정적 영향'};
let relationEditing = null;
const relations = () => [...new Set(records.filter(r=>r.kind==='relation').map(r=>r.id))].map(id=>latest('relation',id));
function relationState(r) {
 if(r.status==='withdrawn') return '철회';
 const p=latest('policy',r.policy_id);
 if(!p||p.version!==r.policy_version||p.review_status!=='reviewed') return '정책 변경 · 재검토 필요';
 return '현재 정책 버전과 일치';
}
function relationCards(list, manage=false) {
 if(!list.length) return '<div class="empty"><p>등록한 기업 연결이 없습니다. 근거 확인 전에는 수혜 기업으로 표시하지 않습니다.</p></div>';
 return list.map(r=>{
 const p=latest('policy',r.policy_id), h=portfolio().holdings.find(h=>h.id===r.company_id);
 const history=records.filter(x=>x.kind==='relation'&&x.id===r.id);
 return `<article class="panel note relation-card"><div class="row"><span class="pill">${e(relationLabels[r.relation_type])}</span><small>${e(relationState(r))}</small></div><div class="flow"><a href="#policy/${e(r.policy_id)}">${e(p?.title||'정책')}</a><span>→</span><a href="#stock/${e(r.company_id)}">${e(h?.name||r.company_id)}</a></div><h3>${e(r.question)}</h3><p class="prewrap">${e(r.answer)}</p>${badge('insufficient')}<p class="meta">종목 영향 판단 보류 · 관계 등록은 매수·매도 신호가 아닙니다.</p><blockquote class="prewrap">${e(r.excerpt)}</blockquote><a class="text-link" href="${e(r.source_url)}" target="_blank" rel="noopener noreferrer">관계 근거 원문 ↗</a><p class="meta">공개일 ${e(r.published_date||'미상')} · 참조 정책 v${r.policy_version} · 관계 v${r.version}<br>사용자 수동 입력 · 자동 검증 아님 · 저장 ${e(stamp(r.recorded_at))}</p><div class="next"><span>다음 확인 조건</span><strong>${e(r.next_condition)}</strong></div>${manage?`<button data-relation-edit="${e(r.id)}">관계 수정·재검토</button>${r.status==='active'?`<form class="withdraw-form" data-id="${e(r.id)}" data-version="${r.version}"><label>철회 이유<input name="reason" required maxlength="5000"></label><button type="submit">관계 철회</button></form>`:''}`:''}<details><summary>근거·관계 변경 이력 (${history.length})</summary>${history.map(v=>`<div class="history"><strong>v${v.version} · ${e(relationLabels[v.relation_type])} · ${v.status==='withdrawn'?'철회':'등록'}</strong><p>${e(v.reason)}</p><p class="prewrap">${e(v.answer)}</p><p class="prewrap">당시 근거: ${e(v.excerpt)}</p><p>다음 조건: ${e(v.next_condition)}</p><a href="${e(v.source_url)}" target="_blank" rel="noopener noreferrer">당시 원문 ↗</a><p class="meta">정책 v${v.policy_version} · 공개일 ${e(v.published_date||'미상')} · 저장 ${e(stamp(v.recorded_at))}</p></div>`).join('')}</details></article>`;
 }).join('');
}
function relationsView() {
 const r=relationEditing, approved=policies().filter(p=>!p.demo&&p.review_status==='reviewed');
 const available=r?approved.filter(p=>p.id===r.policy_id):approved;
 const companies=portfolio().holdings.filter(h=>!['cash','spcx'].includes(h.id)&&(!r||h.id===r.company_id));
 const area=(name,label)=>`<label>${label}<textarea name="${name}" required maxlength="5000">${e(r?.[name]||'')}</textarea></label>`;
 return heading('EVIDENCE CONNECTIONS','정책과 기업의 연결 근거','정책 → 산업 → 기업의 연결을 기록합니다. 계약 확인과 공급 가능성을 구분합니다.')+
 `<div class="two-col main-grid"><section class="panel"><h2>${r?'관계 새 버전 작성':'기업 연결 등록'}</h2>${available.length?`<form id="relation-form"><label>사용자 검토 완료 정책<select name="policy_id">${available.map(p=>`<option value="${e(p.id)}">${e(p.country)} · ${e(p.sector)} · ${e(p.title)} (v${p.version})</option>`).join('')}</select></label><label>기업<select name="company_id">${companies.map(h=>`<option value="${e(h.id)}">${e(h.name)}</option>`).join('')}</select></label><p class="meta">SpaceX / SPCX는 증권 식별 미확인으로 연결 대상에서 제외했습니다.</p><label>관계 유형<select name="relation_type">${Object.entries(relationLabels).map(([k,v])=>`<option value="${k}" ${k===(r?.relation_type||'potential')?'selected':''}>${v}</option>`).join('')}</select></label><label>관계 근거 HTTPS URL<input name="source_url" type="url" required maxlength="2048" value="${e(r?.source_url||'')}"></label><label>원문 공개일 · 미상이면 비움<input name="published_date" type="date" value="${e(r?.published_date||'')}"></label>${area('excerpt','기업과 해당 정책의 관계를 보여주는 발췌')}${area('question','질문')}${area('answer','내 답변 · 연결 이유와 불확실성')}${area('next_condition','다음 확인 조건')}${area('reason','등록·변경 이유')}<label class="review-check"><input name="contract_checked" type="checkbox"> 원문에서 기업명과 해당 계약을 직접 대조했습니다</label><p class="meta">계약 확인 유형은 원문 대조가 필요합니다. 공급 가능성은 추정 관계로 남깁니다.</p><button class="primary" type="submit">연결 근거 저장</button></form>`:'<div class="empty"><p>연결할 정책의 사용자 검토가 먼저 필요합니다.</p><a class="button" href="#sources">정책·출처 관리로 이동</a></div>'}${r?'<button id="relation-new">새 관계 작성</button>':''}</section><section><div class="section-label"><h2>관계와 검토 이력</h2><span>${relations().length}개 관계</span></div>${relationCards(relations(),true)}</section></div>`;
}
function bindRelations() {
 document.querySelectorAll('[data-relation-edit]').forEach(b=>b.onclick=()=>{relationEditing=latest('relation',b.dataset.relationEdit);render();});
 if($('#relation-new'))$('#relation-new').onclick=()=>{relationEditing=null;render();};
 const form=$('#relation-form'), snapshot=relationEditing;
 const versions=Object.fromEntries(policies().map(p=>[p.id,p.version]));
 if(form)form.onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;try{const d=Object.fromEntries(new FormData(form));await post('/api/relations',{...d,id:snapshot?.id,expected_version:snapshot?.version||0,policy_version:versions[d.policy_id],contract_checked:!!d.contract_checked});relationEditing=null;render();toast('정책과 기업의 연결 근거를 저장했습니다.');}catch(err){toast(err.message);b.disabled=false;}};
 document.querySelectorAll('.withdraw-form').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;try{await post('/api/relations',{action:'withdraw',id:f.dataset.id,expected_version:Number(f.dataset.version),reason:new FormData(f).get('reason')});render();toast('관계를 철회했습니다. 이전 기록은 보존됩니다.');}catch(err){toast(err.message);b.disabled=false;}});
}

const collectionLabels={running:'요청 중 · 중단 여부 확인',received:'텍스트 수신 · 검토 필요',proxy_blocked:'환경 프록시 차단',http_error:'HTTP 응답 오류',network_error:'네트워크 오류',timeout:'시간 초과',tls_error:'TLS 검증 실패',import_error:'상세 자료 검증 실패',redirect:'리디렉션 · 대상 검토 필요',empty:'본문 없음',too_large:'크기 제한 초과',unsupported:'미지원 형식',decode_error:'문자 인코딩 확인 필요'};
const collectionRuns=()=>[...new Set(records.filter(r=>r.kind==='collection').map(r=>r.id))].map(id=>latest('collection',id)).sort((a,b)=>b.recorded_at.localeCompare(a.recorded_at));
function collectionView() {
 const runs=collectionRuns(),docs=records.filter(r=>r.kind==='document');
 return heading('COLLECTION LOG','공식 출처 수집과 상태','사이트 접근, 텍스트 수신, 내용 검토는 서로 다른 단계입니다.')+
 `<div class="notice">수집 범위 <span>버튼으로는 공식 진입 페이지 3곳을 요청합니다. 검증한 상세 자료는 별도 수집기로 등록하며, 자동 탐색은 아직 없습니다. 각 요청은 이력으로 남고 같은 출처는 60초 간격으로 요청할 수 있습니다.</span></div><div class="company-grid" style="margin-top:20px">${sourceCatalog.map(s=>{const recent=runs.find(r=>r.source_id===s.id);return `<article class="panel"><h3>${e(s.name)}</h3><a class="text-link" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">공식 사이트 열기 ↗</a><p>${recent?e(collectionLabels[recent.status]||recent.status):'아직 수집 요청 없음'}</p><small>${recent?e(stamp(recent.recorded_at)):'사용자 브라우저 정상 확인 · 2026-10-17'}</small><p><button data-collect="${e(s.id)}">이 출처 수집 요청</button></p></article>`;}).join('')}</div><div class="section-label"><h2>요청 이력</h2><button id="refresh-collection">상태 새로고침</button></div><div class="panel table-wrap"><table><thead><tr><th>출처</th><th>시작 시간</th><th>결과</th><th>응답 구분</th></tr></thead><tbody>${runs.length?runs.map(r=>`<tr><td>${e(r.publisher)}</td><td>${e(stamp(r.started_at))}</td><td>${e(collectionLabels[r.status]||r.status)}</td><td>${r.http_status?`HTTP ${r.http_status}`:'원격 HTTP 상태 미확인'}<details><summary>진단</summary><p class="prewrap">${e(r.message)}</p><small>종료 ${r.finished_at?e(stamp(r.finished_at)):'미기록 · 서버 중단 시 이 상태로 남을 수 있음'}</small></details></td></tr>`).join(''):'<tr><td colspan="4">아직 실행 이력이 없습니다.</td></tr>'}</tbody></table></div><div class="section-label"><h2>수신 자료 · 검토 대기</h2><span>${docs.length}개 고유 본문</span></div><div class="two-col">${docs.length?docs.map(d=>`<article class="panel"><h3>${e(d.publisher)}</h3><span class="pill">${e(d.notice)}</span><p class="meta">수집 ${e(stamp(d.collected_at))} · 원문 공개일 ${e(d.published_at||'미상')}<br>이용권 검토 전 · 본문 일부만 보관</p><details><summary>수신한 텍스트 확인</summary><p class="prewrap">${e(d.excerpt)}</p><small>본문 해시 ${e(d.sha256)}</small></details><a class="text-link" href="${e(d.source_url)}" target="_blank" rel="noopener noreferrer">원문 직접 확인 ↗</a><p><button data-use-document="${e(d.id)}">이 자료로 정책 초안 작성</button></p><p class="meta">개별 정책의 상세 URL과 날짜를 직접 확인해야 합니다. 자동 게시하지 않습니다.</p></article>`).join(''):'<div class="empty"><p>수신한 텍스트가 없습니다. 실패한 요청을 수집 성공으로 처리하지 않습니다.</p></div>'}</div>`;
}
function bindCollection() {
 bindOperations();
 document.querySelectorAll('[data-collect-data]').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='API 요청 중…';try{const result=await post('/api/collect-data',{source_id:b.dataset.collectData});render();toast(collectionLabels[result.status]||result.status);}catch(err){toast(err.message);b.disabled=false;b.textContent='API 자료 수집';}});
 document.querySelectorAll('[data-collect]').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='수집 요청 중…';try{const result=await post('/api/collect',{source_id:b.dataset.collect});render();toast(collectionLabels[result.status]||result.status);}catch(err){toast(err.message);b.disabled=false;b.textContent='이 출처 수집 요청';}});
 $('#refresh-collection').onclick=async()=>{try{await load();render();}catch(err){toast(err.message);}};
 document.querySelectorAll('[data-use-document]').forEach(b=>b.onclick=()=>{const d=latest('document',b.dataset.useDocument);policyEditing={publisher:d.publisher,country:sourceCatalog.find(s=>s.id===d.source_id)?.country||'',excerpt:d.excerpt,source_document_id:d.id,reason:'수신 자료를 참고하여 정책 초안 작성'};location.hash='sources';});
}

const latestRecords=kind=>[...new Set(records.filter(r=>r.kind===kind).map(r=>r.id))].map(id=>latest(kind,id));
function filingsPanel(company='nvda') {
 const filings=latestRecords('filing').filter(r=>r.company_id===company);
 return `<section class="panel" style="margin-top:24px"><h2>SEC 공시 목록 · 본문 미검토</h2><p class="meta">최근 목록에서 10-K·10-Q·8-K와 정정을 최대 10건 수집합니다. 보고 기간·제출일·접수 시각을 구분합니다.</p>${filings.length?`<div class="table-wrap"><table><thead><tr><th>유형</th><th>보고 기준일</th><th>제출일</th><th>공개 접수 시각</th><th>원문</th></tr></thead><tbody>${filings.map(f=>`<tr><td>${e(f.form)}${f.is_amendment?' · 정정':''}</td><td>${e(f.report_date||'미상')}</td><td>${e(f.filing_date||'미상')}</td><td>${f.published_at?e(stamp(f.published_at)):'미상'}</td><td><a href="${e(f.source_url)}" target="_blank" rel="noopener noreferrer">${e(f.accession)} ↗</a><br><a class="text-link" href="#evidence/${e(f.id)}">본문·근거 후보 검토 →</a><details><summary>출처·범위</summary><p>${e(f.company_name)} · CIK ${e(f.cik)}</p><p>목록 수집 ${e(stamp(f.collected_at))} · 본문 상태는 근거 검토에서 확인</p></details></td></tr>`).join('')}</tbody></table></div>`:'<p>아직 실제 공시 목록이 없습니다. 수집 실패를 공시 없음으로 해석하지 않습니다.</p>'}${badge('insufficient')}<p class="meta">목록 수집만으로 실적 개선이나 정책 수혜를 판단하지 않습니다.</p></section>`;
}
function structuredPanel() {
 const awards=latestRecords('award');
 const runs=collectionRuns();
 return `<section style="margin-top:24px"><div class="section-label"><h2>실제 데이터 API</h2><span>홈페이지와 별도 접근</span></div><div class="two-col">${dataSources.map(s=>{const run=runs.find(r=>r.source_id===s.id);return `<article class="panel"><h3>${e(s.name)}</h3><p class="meta">${e(s.scope)}</p><p>${run?e(collectionLabels[run.status]||run.status):'아직 API 수집 기록 없음'}</p><button data-collect-data="${e(s.id)}">API 자료 수집</button>${run?.coverage?`<details><summary>이번 수집 범위</summary><p>조회 ${run.coverage.selected_count}건 · ${run.coverage.has_next===true?'추가 페이지 있음':run.coverage.has_next===false?'이 검색의 다음 페이지 없음':'최근 공시 목록만 확인'}</p><p>${e(run.coverage.scope)}</p>${run.coverage.query_period?`<p>실제 조회 기간 ${e(run.coverage.query_period.start_date)} ~ ${e(run.coverage.query_period.end_date)}</p>`:''}${run.coverage.excluded_name_mismatch?`<p>기업명 불일치 제외 ${run.coverage.excluded_name_mismatch}건</p>`:''}</details>`:''}</article>`;}).join('')}</div>${filingsPanel()}<section class="panel" style="margin-top:24px"><h2>USAspending 지원 검색 결과</h2><p class="meta">미 상무부 지원 중 수혜자 이름 MICRON 검색 후보입니다. MICRONESIA처럼 다른 이름은 제외합니다. 마이크론 상장사·자회사 및 CHIPS 정책과의 연결은 별도 검토가 필요합니다.</p><p class="meta">Award Amount와 Total Outlays를 분리합니다. 검색 기간의 실제 지출 합계나 전체 지원 규모로 합산하지 않습니다. 금액 단위는 USD입니다.</p>${awards.length?awards.map(a=>`<article class="history"><h3>${e(a.recipient)}</h3><p>${e(a.agency||'기관 미상')} · ${e(a.award_id)}</p><div class="two-col"><div>Award Amount<strong class="amount">${e(a.award_amount_usd??'자료 없음')}</strong></div><div>Total Outlays<strong class="amount">${e(a.total_outlays_usd??'자료 없음')}</strong></div></div><p class="prewrap">${e(a.description||'설명 없음')}</p><p class="meta">시작 ${e(a.start_date||'미상')} · 종료 ${e(a.end_date||'미상')} · 자료 수정 ${e(a.modified_date||'미상')}<br>수집 ${e(stamp(a.collected_at))} · 원문 공개 시각 미상</p><a href="${e(a.source_url)}" class="text-link" target="_blank" rel="noopener noreferrer">지원 원문 ↗</a><details><summary>금액 변경 이력</summary>${records.filter(r=>r.kind==='award'&&r.id===a.id).map(r=>`<p>v${r.version} · ${e(stamp(r.collected_at))}<br>Award Amount ${e(r.award_amount_usd??'자료 없음')} / Total Outlays ${e(r.total_outlays_usd??'자료 없음')}</p>`).join('')}</details></article>`).join(''):'<p>저장된 검색 결과가 없습니다. 이 화면만으로 지원이 없다고 판단하지 않습니다.</p>'}${badge('insufficient')}<div class="next"><span>다음 확인 조건</span><strong>수혜 법인·지원 프로그램·지급 내역을 원문에서 대조</strong></div></section></section>`;
}

function evidenceView(filingId) {
 const filings=latestRecords('filing'),selected=filings.find(f=>f.id===filingId)||filings.find(f=>f.form==='10-Q')||filings[0];
 if(!selected)return heading('FILING EVIDENCE','공시 근거 검토','먼저 SEC 공시 목록을 수집하세요.')+'<a class="button" href="#collection">수집 화면 →</a>';
 const bodies=records.filter(r=>r.kind==='filing_body'&&r.filing_id===selected.id).sort((a,b)=>b.recorded_at.localeCompare(a.recorded_at));
 const body=bodies[0], candidates=body?records.filter(r=>r.kind==='evidence'&&r.body_id===body.id):[];
 const topicLabels={capex:'설비투자',support:'정책 지원',restriction:'수출 규제',contract:'계약·구매 약정'};
 return heading('EVIDENCE / NVIDIA','공시 문단에서 근거를 확인하다.','키워드 기반 근거 후보입니다. AI 해석·수치 추출·기회 판정은 수행하지 않습니다.')+
 `<div class="filters evidence-filters"><label>공시 선택<select id="evidence-filing">${filings.map(f=>`<option value="${e(f.id)}" ${f.id===selected.id?'selected':''}>${e(f.form)} · ${e(f.filing_date)} · ${e(f.accession)}</option>`).join('')}</select></label><button data-fetch-filing="${e(selected.id)}">본문 수집·근거 후보 추출</button></div><p class="meta">보고 기준 ${e(selected.report_date||'미상')} · 접수 ${selected.published_at?e(stamp(selected.published_at)):'미상'} · 실제 수집 ${body?e(stamp(body.collected_at)):'미수집'}</p>${body?`<div class="notice">추출 범위 <span>${e(body.coverage)} 원문 해시와 문단을 보존합니다.</span></div><div class="stats evidence-stats">${Object.entries(topicLabels).map(([key,label])=>`<div><span>${label}</span><strong>${body.counts[key]||0}<small>문단 일치</small></strong><p>표시 ${candidates.filter(c=>c.topic===key).length}개 · 0은 관련 사실 부재를 뜻하지 않음</p></div>`).join('')}</div>`:'<div class="empty"><p>아직 이 공시 본문을 수집하지 않았습니다.</p></div>'}<section class="panel evidence-tools"><div class="filters"><label>검토 상태<select id="evidence-status"><option value="all">전체</option><option value="pending">검토 전</option><option value="accepted">채택</option><option value="dismissed">제외</option></select></label><label>주제<select id="evidence-topic"><option value="all">전체 주제</option>${Object.entries(topicLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>본문·질문 검색<input id="evidence-search" type="search" placeholder="예: export, 구매 약정" maxlength="200"></label></div><p id="evidence-count" role="status"></p></section><div class="two-col">${candidates.map(c=>{const review=latest('evidence_review',c.id);const history=records.filter(r=>r.kind==='evidence_review'&&r.id===c.id);return `<article class="panel evidence-candidate" data-topic="${e(c.topic)}" data-status="${e(review?.status||'pending')}"><div class="row"><span class="pill">${e(c.label)}</span><small>${review?(review.status==='accepted'?'사용자 채택 · 종목 신호 아님':'사용자 제외'):'검토 전 후보'}</small></div><h3>${e(c.question)}</h3><p>${e(review?.answer||c.answer)}</p>${badge('insufficient')}<blockquote class="prewrap">${e(c.quote)}</blockquote><a class="text-link" href="${e(c.locator_url)}" target="_blank" rel="noopener noreferrer">원문 위치 확인 ↗</a><p class="meta">저장된 서술 문단 #${c.paragraph_index} · ${e(c.parser_version)}<br>원문 앵커 ${c.anchor?e(c.anchor):'없음 · 아래 저장 본문에서 문단 번호로 확인'}</p><div class="next"><span>다음 확인 조건</span><strong>${e(review?.next_condition||c.next_condition)}</strong></div><details><summary>후보 검토·질문 답변 기록</summary><form class="evidence-review" data-id="${e(c.id)}" data-version="${review?.version||0}"><label>판단<select name="status"><option value="accepted" ${review?.status==='accepted'?'selected':''}>질문의 근거로 채택</option><option value="dismissed" ${review?.status==='dismissed'?'selected':''}>관련 근거에서 제외</option></select></label><label>내 답변<textarea name="answer" required maxlength="5000">${e(review?.answer||'')}</textarea></label><label>다음 확인 조건<textarea name="next_condition" required maxlength="5000">${e(review?.next_condition||c.next_condition)}</textarea></label><label>검토·변경 이유<input name="reason" required maxlength="5000"></label><label class="review-check"><input type="checkbox" name="source_checked"> 원문 문맥을 직접 대조했습니다</label><button type="submit">검토 기록 저장</button></form></details>${history.length?`<details><summary>검토 이력 (${history.length})</summary>${history.map(r=>`<div class="history"><strong>v${r.version} · ${r.status==='accepted'?'채택':'제외'}</strong><p>${e(r.answer)}</p><p>이유: ${e(r.reason)}</p><p>다음 조건: ${e(r.next_condition)}</p><small>${e(stamp(r.recorded_at))}</small></div>`).join('')}</details>`:''}</article>`;}).join('')}</div>${body?`<details class="panel"><summary>저장된 서술 본문 · ${body.paragraphs.length}개 문단</summary><p class="meta">표·숨김 XBRL을 제외한 정규화 텍스트입니다. 원문 HTML 전체와 동일하지 않습니다.</p>${body.paragraphs.map(p=>`<p class="prewrap" id="paragraph-${p.index}"><small>#${p.index}</small> ${e(p.text)}</p>`).join('')}</details><details class="panel"><summary>본문 수집 버전 (${bodies.length})</summary>${bodies.map(b=>`<p class="meta">${e(stamp(b.collected_at))}<br>해시 ${e(b.sha256)} · 후보 ${records.filter(r=>r.kind==='evidence'&&r.body_id===b.id).length}개</p>`).join('')}</details>`:''}`;
}
function bindEvidence() {
 if($('#evidence-status')){
  $('#evidence-status').value=evidenceFilter.status;$('#evidence-topic').value=evidenceFilter.topic;$('#evidence-search').value=evidenceFilter.query;
  const filter=()=>{evidenceFilter={status:$('#evidence-status').value,topic:$('#evidence-topic').value,query:$('#evidence-search').value};let visible=0,total=0;document.querySelectorAll('.evidence-candidate').forEach(card=>{total++;card.hidden=(evidenceFilter.status!=='all'&&card.dataset.status!==evidenceFilter.status)||(evidenceFilter.topic!=='all'&&card.dataset.topic!==evidenceFilter.topic)||!card.textContent.toLowerCase().includes(evidenceFilter.query.trim().toLowerCase());if(!card.hidden)visible++;});$('#evidence-count').textContent=`전체 ${total}개 중 ${visible}개 표시${visible?'':' · 조건에 맞는 후보가 없습니다.'}`;};
  $('#evidence-status').onchange=filter;$('#evidence-topic').onchange=filter;$('#evidence-search').oninput=filter;filter();
 }

 if($('#evidence-filing'))$('#evidence-filing').onchange=ev=>location.hash='evidence/'+ev.target.value;
 document.querySelectorAll('[data-fetch-filing]').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='본문 수집 중…';try{const result=await post('/api/collect-filing',{filing_id:b.dataset.fetchFiling});render();toast(result.status==='received'?`근거 후보 ${result.count}개 · 검토 전`:(collectionLabels[result.status]||result.status));}catch(err){toast(err.message);b.disabled=false;b.textContent='본문 수집·근거 후보 추출';}});
 document.querySelectorAll('.evidence-review').forEach(form=>form.onsubmit=async ev=>{ev.preventDefault();const button=ev.submitter;button.disabled=true;try{const data=Object.fromEntries(new FormData(form));await post('/api/evidence-review',{...data,evidence_id:form.dataset.id,expected_version:Number(form.dataset.version),source_checked:!!data.source_checked});render();toast('검토를 새 버전으로 저장했습니다. 종목 신호는 바뀌지 않습니다.');}catch(err){toast(err.message);button.disabled=false;}});
}

const progressStages={payment:'정부 집행',capex:'기업 투자',operation:'가동·공급',revenue:'매출 반영'};
const progressRoles={supports:'지지 근거',contradicts:'반대 근거',uncertain:'연결 불확실'};
let progressEditing=null;
const progressRecords=()=>[...new Set(records.filter(r=>r.kind==='progress').map(r=>r.id))].map(id=>latest('progress',id));
function progressStale(r){
 const relation=latest('relation',r.relation_id), policy=latest('policy',r.policy_id), review=latest('evidence_review',r.evidence_id);
 return !relation||relation.status!=='active'||relation.version!==r.relation_version||!policy||policy.version!==r.policy_version||policy.review_status!=='reviewed'||!review||review.version!==r.review_version||review.status!=='accepted';
}
function progressCards(list,manage=false){
 if(!list.length)return '<div class="empty"><p>정책 실행과 기업 공시를 연결한 검토 기록이 없습니다. 미확인은 집행 실패를 뜻하지 않습니다.</p></div>';
 return list.map(r=>`<article class="panel note progress-card"><div class="row"><span class="pill">${e(progressStages[r.stage])} · ${e(progressRoles[r.evidence_role])}</span><small>${progressStale(r)?'참조 변경 · 재검토 필요':'참조 버전 일치 · 사용자 판단'}</small></div><div class="flow"><a href="#policy/${e(r.policy_id)}">${e(latest('policy',r.policy_id)?.title||'정책')}</a><span>→</span><a href="#stock/${e(r.company_id)}">${e(portfolio().holdings.find(h=>h.id===r.company_id)?.name||r.company_id)}</a></div><h3>${e(r.question)}</h3><p class="prewrap">${e(r.answer)}</p>${badge('insufficient')}<p class="meta">자료 기준 ${e(r.observed_date)} · 공개 ${e(stamp(r.published_at))} · 기록 ${e(stamp(r.recorded_at))}</p><blockquote>${e(r.quote)}</blockquote><a class="text-link" href="${e(r.source_url)}" target="_blank" rel="noopener noreferrer">공시 원문 ↗</a><div class="next"><span>다음 확인 조건</span><strong>${e(r.next_condition)}</strong></div><p class="meta">정책 v${r.policy_version} · 관계 v${r.relation_version} · 공시 검토 v${r.review_version}<br>지지 근거 등록은 정책 집행 완료나 종목 기회 신호를 뜻하지 않습니다.</p>${manage?`<button data-progress-edit="${e(r.id)}">추적 기록 재검토</button>`:''}<details><summary>추적 이력</summary>${records.filter(x=>x.kind==='progress'&&x.id===r.id).map(v=>`<div class="history"><strong>v${v.version} · ${e(progressStages[v.stage])} · ${e(progressRoles[v.evidence_role])}</strong><p>${e(v.question)}</p><p>${e(v.answer)}</p><p>이유: ${e(v.reason)}</p><p>다음 조건: ${e(v.next_condition)}</p><blockquote>${e(v.quote)}</blockquote><a href="${e(v.source_url)}" target="_blank" rel="noopener noreferrer">당시 원문 ↗</a><p class="meta">기준 ${e(v.observed_date)} · 공개 ${e(stamp(v.published_at))} · 저장 ${e(stamp(v.recorded_at))}<br>관계 v${v.relation_version} · 검토 v${v.review_version}</p></div>`).join('')}</details></article>`).join('');
}
function progressPanel(){
 const r=progressEditing;
 const eligible=relations().filter(x=>x.status==='active'&&relationState(x)==='현재 정책 버전과 일치'&&(!r||x.id===r.relation_id));
 const area=(key,label)=>`<label>${label}<textarea name="${key}" required maxlength="5000">${e(r?.[key]||'')}</textarea></label>`;
 return `<section class="progress-section"><div class="section-label"><h2>정책 실행 → 기업 실적 추적</h2><span>사용자 근거 검토</span></div><div class="flow progress-flow">${Object.values(progressStages).map(label=>`<span class="pill">${e(label)}</span>`).join('<span>→</span>')}</div><p class="meta">각 단계는 별도로 확인합니다. 기업 설비투자를 정부 지급액으로, 구매 약정을 고객 수주로 해석하지 않습니다.</p><div class="two-col"><section class="panel"><h3>${r?'추적 기록 새 버전':'공시 근거 연결'}</h3>${eligible.length?`<form id="progress-form"><label>검토된 정책·기업 관계<select name="relation_id">${eligible.map(x=>`<option value="${e(x.id)}">${e(latest('policy',x.policy_id)?.title)} · ${e(x.company_id)}</option>`).join('')}</select></label><label>채택된 해당 기업 공시 후보<select name="evidence_id" required></select></label><p id="progress-evidence-note" class="meta"></p><label>확인할 단계<select name="stage">${Object.entries(progressStages).map(([k,v])=>`<option value="${k}" ${r?.stage===k?'selected':''}>${v}</option>`).join('')}</select></label><label>근거 방향<select name="evidence_role">${Object.entries(progressRoles).map(([k,v])=>`<option value="${k}" ${(r?.evidence_role||'uncertain')===k?'selected':''}>${v}</option>`).join('')}</select></label><label>자료 기준일<input name="observed_date" type="date" required value="${e(r?.observed_date||'')}"></label>${area('question','질문')}${area('answer','답변 · 정책 연결 이유와 반례·불확실성')}${area('next_condition','다음 확인 조건')}${area('reason','등록·변경 이유')}<label class="review-check"><input type="checkbox" name="link_checked" required> 정책·기업·해당 단계와 원문 문맥의 연결을 대조했습니다</label><button type="submit">추적 기록 저장</button></form>`:'<p>최신 정책에 맞춰 검토한 활성 기업 관계가 필요합니다. 위에서 정책과 기업을 먼저 연결하세요.</p>'}<p><a class="text-link" href="#evidence">공시 후보 검토로 이동 →</a></p>${r?'<button id="progress-new">새 추적 기록 작성</button>':''}</section><section>${progressCards(progressRecords(),true)}</section></div></section>`;
}
function bindProgress(){
 document.querySelectorAll('[data-progress-edit]').forEach(b=>b.onclick=()=>{progressEditing=latest('progress',b.dataset.progressEdit);render();});
 if($('#progress-new'))$('#progress-new').onclick=()=>{progressEditing=null;render();};
 const form=$('#progress-form'),snapshot=progressEditing;
 if(!form)return;
 const fill=()=>{
  const relation=latest('relation',form.elements.relation_id.value);
  const candidates=records.filter(r=>r.kind==='evidence'&&!r.demo&&r.company_id===relation.company_id&&latest('evidence_review',r.id)?.status==='accepted');
  form.elements.evidence_id.innerHTML='<option value="">공시 근거 선택</option>'+candidates.map(c=>`<option value="${e(c.id)}" ${snapshot?.evidence_id===c.id?'selected':''}>${e(c.label)} · ${e(c.report_date)} · 문단 ${c.paragraph_index}</option>`).join('');
  $('#progress-evidence-note').textContent=candidates.length?'채택한 후보도 정책 수혜를 입증하는지는 별도로 대조해야 합니다.':'이 기업의 채택된 공시 후보가 없습니다. 공시 근거 검토에서 먼저 확인하세요.';
 };
 form.elements.relation_id.onchange=fill;fill();
 const relationVersions=Object.fromEntries(relations().map(r=>[r.id,r.version]));
 const reviewVersions=Object.fromEntries(records.filter(r=>r.kind==='evidence').map(r=>[r.id,latest('evidence_review',r.id)?.version]));
 form.onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;try{const d=Object.fromEntries(new FormData(form));await post('/api/progress',{...d,id:snapshot?.id,expected_version:snapshot?.version||0,relation_version:relationVersions[d.relation_id],review_version:reviewVersions[d.evidence_id],link_checked:!!d.link_checked});progressEditing=null;render();toast('추적 기록을 저장했습니다. 종목 신호는 판단 보류입니다.');}catch(err){toast(err.message);b.disabled=false;}};
}

// Daily attention and weekend reflection share the server's derived queue.
let workbench={queue:[],targets:[],reviews:[],today:''}, reviewTarget=null, archiveData=null;
const targetLabels={policy:'정책',evidence:'공시 후보',relation:'정책·기업 관계',progress:'실행 추적',review:'주말 기록',evidence_review:'공시 검토',filing:'공시 목록'};
function attentionSummary(){
 const changed=workbench.queue.filter(q=>q.reasons.some(s=>s.includes('변경'))).length;
 const due=workbench.queue.filter(q=>q.reasons.includes('재확인 예정일 도래')).length;
 return `<section class="panel attention-summary"><div class="row"><div><span class="eyebrow">ACTUAL RECORDS / 실제 저장 기록</span><h2>오늘 확인할 근거</h2></div><a class="button primary" href="#review">평일 확인·주말 복기 →</a></div><div class="stats"><div><span>확인 대상</span><strong>${workbench.queue.length}<small>개</small></strong><p>실제 정책·공시·연결 기록</p></div><div><span>참조 변경</span><strong>${changed}<small>개</small></strong><p>이전 판단의 근거 재확인</p></div><div><span>재확인 일정 도래</span><strong>${due}<small>개</small></strong><p>한국시간 ${e(workbench.today)}</p></div></div><p class="meta">앱에 저장된 자료 기준입니다. 앱을 열거나 최신 기록을 불러올 때 갱신되며, 백그라운드 알림은 아닙니다. 항목 수는 종목 기회·위기 점수가 아닙니다.</p>${workbench.collection_problems?.length?`<p class="collection-warning">최근 수집 미완료·오류 ${workbench.collection_problems.length}개 출처 · <a class="text-link" href="#collection">수집 상태 확인 →</a></p>`:''}</section>`;
}
function reviewView(){
 const selected=reviewTarget&&workbench.targets.find(t=>t.kind===reviewTarget.kind&&t.id===reviewTarget.id);
 const note=selected&&workbench.reviews.find(n=>n.target_kind===selected.kind&&n.target_id===selected.id);
 const defaultDue=workbench.today?new Date(Date.parse(workbench.today+'T12:00:00Z')+7*86400000).toISOString().slice(0,10):'';
 const area=(key,label,value)=>`<label>${label}<textarea name="${key}" required maxlength="5000">${e(value||'')}</textarea></label>`;
 return heading('DAILY CHECK / WEEKEND REVIEW','변화를 확인하고, 주말에 답하다.','원문 검토와 내 생각의 기록을 구분합니다. 복기 저장만으로 근거 검토가 완료되지는 않습니다.', '<button id="refresh-workbench">최신 기록 불러오기</button>')+attentionSummary()+
 `<div class="review-layout"><section><div class="section-label"><h2>확인 목록</h2><select id="queue-filter" aria-label="확인 목록 필터"><option value="all">전체</option><option value="changed">근거 변경</option><option value="due">예정일 도래</option><option value="pending">원문 검토 대기</option></select></div><div id="review-queue">${workbench.queue.length?workbench.queue.map(q=>`<article class="panel queue-card" data-changed="${q.reasons.some(s=>s.includes('변경'))}" data-due="${q.reasons.includes('재확인 예정일 도래')}" data-pending="${q.reasons.some(s=>s.includes('대기'))}"><div class="row"><span class="pill">${e(targetLabels[q.target_kind])}</span>${badge(q.signal)}</div><p class="meta">${e(q.display_title)}</p><h3>${e(q.question)}</h3><p>${e(q.answer)}</p><p class="meta">${q.reasons.map(e).join(' · ')}${q.due_date?' · 예정 '+e(q.due_date):''}</p><div class="next"><span>다음 확인 조건</span><strong>${e(q.next_condition)}</strong></div><div class="review-actions"><a class="button" href="${e(q.route)}">원문·근거 검토</a><button data-review-kind="${e(q.target_kind)}" data-review-id="${e(q.target_id)}">주말 답변 작성</button></div></article>`).join(''):'<div class="empty"><p>현재 저장된 기록에 확인 대기 항목이 없습니다. 시장 위험이 없다는 뜻은 아닙니다.</p></div>'}</div><p id="queue-empty" hidden>선택한 조건의 항목이 없습니다.</p></section>
 <section class="panel review-editor"><h2>${note?'주말 답변 새 버전':'주말 질문·답변'}</h2><label>연결할 실제 기록<select id="review-target"><option value="">기록 선택</option>${workbench.targets.map((t,i)=>`<option value="${i}" ${selected?.kind===t.kind&&selected?.id===t.id?'selected':''}>${e(targetLabels[t.kind])} · ${e(t.display_title)} · v${t.version}</option>`).join('')}</select></label>${selected?`<p class="meta">연결: ${e(targetLabels[selected.kind])} v${selected.version} · ${note&&note.context_fingerprint!==selected.context_fingerprint?'이전 복기 이후 근거 변경':'현재 저장된 근거 기준'}</p><p>원래 질문: ${e(selected.question||selected.title)}</p><p class="meta">${e(selected.display_title)}</p><details><summary>연결된 근거와 원문 확인</summary><p>${e(selected.answer||'답변 미작성')}</p><blockquote>${e(selected.quote||selected.excerpt||'발췌는 근거 화면에서 확인하세요.')}</blockquote><a class="text-link" href="${e(({policy:'#sources',evidence:'#evidence/'+selected.filing_id,relation:'#relations',progress:'#relations'})[selected.kind])}">근거 검토 화면 →</a></details>${badge(selected.signal||'insufficient')}<p class="meta">신호는 연결 기록에서 가져옵니다. 아래 답변은 사용자 해석이며 종목 신호를 변경하지 않습니다.</p><form id="weekend-form">${area('question','복기 질문',note?.question||selected.question||selected.title)}${area('answer','내 답변 · 확인한 점과 반례·불확실성',note?.answer)}${area('next_condition','다음 확인 조건',note?.next_condition||selected.next_condition)}<label>재확인 예정일 · 한국시간<input type="date" name="due_date" required value="${e(note?.due_date||defaultDue)}"></label>${area('reason','판단·변경 이유','')}<button class="primary" type="submit">주말 답변 저장</button></form>${note?`<details><summary>이전 주말 답변</summary>${records.filter(r=>r.kind==='review'&&r.id===note.id).map(r=>`<div class="history"><strong>v${r.version} · ${e(stamp(r.recorded_at))}</strong><p>${e(r.question)}</p><p>${e(r.answer)}</p><p>이유: ${e(r.reason)}</p><p>다음 조건: ${e(r.next_condition)} · 예정 ${e(r.due_date)}</p><small>참조 ${e(targetLabels[r.target_kind])} v${r.target_version}</small></div>`).join('')}</details>`:''}`:'<div class="empty"><p>왼쪽 확인 목록이나 위 목록에서 실제 기록을 선택하세요.</p><a class="text-link" href="#sources">정책 자료 등록 →</a></div>'}</section></div>`;
}
function bindReview(){
 $('#refresh-workbench').onclick=async()=>{try{await load();render();toast('최신 기록을 불러왔습니다.');}catch(err){toast(err.message);}};
 $('#review-target').onchange=ev=>{const t=ev.target.value===''?null:workbench.targets[Number(ev.target.value)];reviewTarget=t?{kind:t.kind,id:t.id}:null;render();};
 document.querySelectorAll('[data-review-kind]').forEach(b=>b.onclick=()=>{reviewTarget={kind:b.dataset.reviewKind,id:b.dataset.reviewId};render();$('.review-editor').scrollIntoView({behavior:'smooth',block:'start'});});
 $('#queue-filter').onchange=ev=>{let count=0;document.querySelectorAll('.queue-card').forEach(c=>{c.hidden=ev.target.value!=='all'&&c.dataset[ev.target.value]!=='true';if(!c.hidden)count++;});$('#queue-empty').hidden=count>0;};
 const form=$('#weekend-form');if(!form)return;
 const target=workbench.targets.find(t=>t.kind===reviewTarget.kind&&t.id===reviewTarget.id);
 const note=workbench.reviews.find(n=>n.target_kind===target.kind&&n.target_id===target.id);
 form.onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;try{await post('/api/reviews',{...Object.fromEntries(new FormData(form)),id:note?.id,expected_version:note?.version||0,target_kind:target.kind,target_id:target.id,target_version:target.version,context_fingerprint:target.context_fingerprint});render();toast('주말 답변과 재확인 일정을 저장했습니다. 원문 검토 상태는 그대로 유지됩니다.');}catch(err){toast(err.message);b.disabled=false;}};
}
function historyView(){
 return heading('APP HISTORY','그날 저장돼 있던 근거로 돌아가다.','선택 날짜의 한국시간 하루 끝까지 앱에 저장됐고, 알려진 공개일도 그날 이내인 기록만 표시합니다.')+`<div class="panel"><form id="archive-form" class="archive-controls"><label>조회 날짜 · 한국시간<input id="archive-date" type="date" required value="${e(archiveData?.at||workbench.today)}"></label><button type="submit">당시 기록 조회</button></form><p class="meta">시장 전체의 과거 정보 재현이 아닙니다. 나중에 수집한 과거 공시는 과거 날짜에 소급 표시하지 않습니다. 공개일 미상 기록은 저장 시각 기준이며, 별도로 표시합니다. 현재 화면의 판단·검토 상태를 과거 기록에 덧붙이지 않습니다.</p></div><div id="archive-result" aria-live="polite">${archiveData?archiveResults():'<div class="empty"><p>날짜를 선택해 조회하세요.</p></div>'}</div>`;
}
function archiveResults(){
 const data=archiveData;
 const fields={title:'제목',question:'질문',answer:'답변',quote:'발췌',signal:'신호',stage:'단계',review_status:'검토 상태',status:'상태',evidence_role:'근거 방향',next_condition:'다음 조건',due_date:'재확인 예정',reason:'이유'};
 const show=(r,k)=>k==='signal'?labels[r[k]]:k==='stage'?(r.kind==='policy'?policyStages[r[k]]:progressStages[r[k]]):k==='evidence_role'?progressRoles[r[k]]:r[k];
 return `<div class="section-label"><h2>${e(data.at)}까지의 저장 기록</h2><a class="button" href="/api/history?at=${e(data.at)}" download="research-history-${e(data.at)}.json">이 시점 JSON 내보내기 ↓</a></div><p class="meta">${data.current.length}개 대상 · ${data.records.length}개 버전 · 날짜·참조 조건으로 제외 ${data.excluded_versions}개 버전</p><div class="archive-grid">${data.current.length?data.current.map(r=>{const versions=data.records.filter(v=>v.kind===r.kind&&v.id===r.id).sort((a,b)=>b.version-a.version);return `<article class="panel archive-card"><div class="row"><span class="pill">${e(targetLabels[r.kind]||r.kind)}</span><small>당시 v${r.version}</small></div><h3>${e(r.title||r.question||(r.form?[r.form,r.report_date,r.accession].filter(Boolean).join(' · '):'기록'))}</h3><p class="prewrap">${e(r.answer||r.quote||r.source_question||'답변 없는 자료 기록')}</p>${r.signal?badge(r.signal):''}${r.next_condition?`<div class="next"><span>당시 다음 확인 조건</span><strong>${e(r.next_condition)}</strong></div>`:''}<p class="meta">저장 ${e(stamp(r.recorded_at))}<br>공개 ${e(r.published_at||r.published_date||'미상 · 저장 시각 기준')}</p>${r.source_url?`<a class="text-link" href="${e(r.source_url)}" target="_blank" rel="noopener noreferrer">당시 저장한 원문 링크 ↗</a>`:''}<details><summary>그날까지의 변경 이력 (${versions.length})</summary>${versions.map((v,i)=>{const prev=versions[i+1];const changes=Object.keys(fields).filter(k=>v[k]!==undefined&&(!prev||JSON.stringify(v[k])!==JSON.stringify(prev[k])));return `<div class="history"><strong>v${v.version} · ${e(stamp(v.recorded_at))}</strong>${changes.map(k=>`<p><b>${e(fields[k])}</b>${prev&&prev[k]!==undefined?`<br>이전: ${e(show(prev,k))}`:''}<br>${prev?'변경: ':''}${e(show(v,k))}</p>`).join('')||'<p>연결 참조·메타데이터 변경</p>'}</div>`;}).join('')}</details></article>`;}).join(''):'<div class="empty"><p>이 날짜까지 앱에 저장된 실제 기록이 없습니다.</p></div>'}</div>`;
}
function bindHistory(){
 $('#archive-form').onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;const at=$('#archive-date').value;try{const res=await fetch('/api/history?at='+encodeURIComponent(at));const data=await res.json();if(!res.ok)throw Error(data.error);archiveData=data;if(location.hash==='#history')render();}catch(err){toast(err.message);b.disabled=false;}};
}


// Operational readiness is separate from market analysis and investment signals.
const jobLabels={running:'확인 중',completed:'수집 완료 · 원문 검토 필요',partial:'일부 실패 · 기존 자료 보존',interrupted:'중단됨'};
function refreshPanel(){
 const job=refreshState.jobs[0],running=refreshState.active;
 return `<section class="panel refresh-panel"><div class="row"><div><p class="eyebrow">OFFICIAL SOURCES</p><h2>새 근거 확인</h2></div><span class="pill">${job?e(jobLabels[job.status]||job.status):'아직 묶음 확인 전'}</span></div><p>공시 목록 → 지원 검색 → 정책 원문 → 최신 정기 공시 본문을 차례로 확인합니다. 기존 검토와 판단은 자동 변경하지 않습니다.</p><div class="review-actions"><button id="refresh-all" class="primary" ${running?'disabled':''}>${running?'자료 확인 중…':'공식 자료 한 번에 확인'}</button>${job&&job.status!=='completed'&&!running?'<button id="refresh-failed">실패·미완료만 재시도</button>':''}<button id="refresh-status">상태 새로고침</button></div><p class="meta">같은 묶음은 60초 후 재요청할 수 있습니다. 이전 실행이 중단된 경우 마지막 기록 10분 후 다시 시작할 수 있습니다. 실패한 출처의 기존 자료는 보존합니다.</p><label class="review-check"><input id="daily-refresh" type="checkbox" ${refreshState.settings.enabled?'checked':''}> 앱이 켜져 있는 동안 24시간마다 공식 자료 확인</label><p class="meta">${refreshState.settings.enabled?'다음 확인: '+e(stamp(refreshState.next_due_at)):'자동 확인 꺼짐'} · 앱 종료·PC 절전 중에는 실행하지 않습니다. 다시 실행하면 지난 예정 작업을 한 번 확인합니다. 기본값은 꺼짐입니다.</p><div id="refresh-results" aria-live="polite">${job?`<p class="meta">시작 ${e(stamp(job.started_at))} · ${job.trigger==='daily'?'정기 확인':'직접 요청'}${job.status==='running'&&!running?' · 이전 실행 미완료, 중단 여부 확인 필요':''}</p><ul class="refresh-results">${job.tasks.map(key=>{const result=job.results[key];return `<li><strong>${e(refreshState.tasks[key])}</strong><span>${result?e(result.status==='received'?'수신 완료 · 검토 전':(collectionLabels[result.status]||result.status)):key===job.current_task?'요청 중':'대기'}</span>${result?.http_status?`<p>HTTP ${e(result.http_status)} · 기존 자료는 보존했습니다.</p>`:''}${result?.message?`<p>${e(result.message)}</p>`:''}</li>`;}).join('')}</ul>`:''}</div><details><summary>최근 묶음 확인 이력 (${refreshState.jobs.length})</summary>${refreshState.jobs.map(j=>`<p>${e(stamp(j.started_at))} · ${e(jobLabels[j.status]||j.status)} · ${Object.keys(j.results).length}/${j.tasks.length}개 처리</p>`).join('')||'<p>실행 기록이 없습니다.</p>'}</details></section>`;
}
function startView(){
 const c=readinessState.counts;
 const steps=[
  ['1. 공식 자료 확인','갱신 성공과 원문 검토는 별개입니다. 아래에서 수집 결과와 최근 성공 시각을 확인하세요.','#collection','수집 이력 열기'],
  ['2. 정책 원문 검토',`실제 정책 ${c.policies}건 중 사용자 검토 완료 ${c.policies_reviewed}건. 발표·예산·집행을 구분해 답변과 다음 조건을 남기세요.`,'#sources','정책 검토하기'],
  ['3. 공시 후보 검토',`근거 후보 ${c.evidence}건 중 검토 전 ${c.evidence_pending}건, 채택 ${c.evidence_accepted}건. 원문 문맥과 반례를 확인하세요.`,'#evidence','공시 후보 확인'],
  ['4. 정책과 기업 연결',`활성 관계 ${c.relations}건, 실행 추적 ${c.progress}건. 관련성을 입증하지 못하면 연결을 만들지 않고 판단 보류를 유지하세요.`,'#relations','연결 근거 확인'],
  ['5. 내 답변과 다음 일정',`실제 자료에 연결한 주말 기록 ${c.reviews}건. 다음 확인 조건과 재확인 날짜를 저장한 뒤 이전 버전을 확인하세요.`,'#review','질문·복기 작성'],
  ['6. 저장과 재시작 검증','앱을 종료하고 다시 실행해 기록이 남는지 확인하세요. 날짜별 기록과 JSON 내보내기도 확인할 수 있습니다.','#history','저장 이력 확인']
 ];
 return heading('START / PERSONAL RESEARCH','오늘의 검증을 시작하세요.','자료를 확인하고, 근거를 검토하고, 내 판단을 기록하는 순서입니다.')+`<div class="notice">${readinessState.usage_mode==='practice'?'연습 모드':'개인 모드'}<span>${readinessState.usage_mode==='practice'?'이 화면에서 저장한 기록은 연습 DB에 남습니다. 개인 DB에는 반영되지 않습니다.':'이 화면에서 저장하면 개인 기록이 변경됩니다. 연습하려면 Practice-Windows.bat로 실행하세요.'}</span></div><div class="start-steps">${steps.map(([title,description,url,label])=>`<article class="panel"><h2>${title}</h2><p>${e(description)}</p><a class="button" href="${url}">${label} →</a></article>`).join('')}</div>`+refreshPanel()+`<section class="panel" style="margin-top:24px"><h2>실제 자료의 확인 상태</h2><p class="meta">${e(readinessState.notice)} 신호 개수나 투자 점수가 아닙니다.</p><div class="table-wrap"><table><thead><tr><th>출처</th><th>최근 요청</th><th>마지막 성공</th><th>다음 확인</th></tr></thead><tbody>${readinessState.sources.length?readinessState.sources.map(s=>`<tr><td>${e(s.name)}</td><td>${e(collectionLabels[s.status]||s.status)}</td><td>${s.last_success_at?e(stamp(s.last_success_at)):'성공 기록 없음'}</td><td>${s.check_due?'갱신 확인 필요':'24시간 내 수신 기록 있음'}</td></tr>`).join(''):'<tr><td colspan="4">수집 기록이 없습니다. 자료 부족은 판단 보류입니다.</td></tr>'}</tbody></table></div></section><section class="panel" style="margin-top:24px"><h2>이번 버전의 범위</h2><p>정책·공시 원문 검토, 연결 근거, 실행 추적, 주말 기록과 저장 이력을 검증할 수 있습니다. AI 답변·자동 종목 신호·실시간 가격·손익·13F·회귀분석은 아직 제공하지 않습니다.</p><p>자료가 부족한 종목은 판단 보류입니다. 산업 시연 사례와 실제 자료는 별도 기록입니다.</p></section>`;
}
function bindOperations(){
 const run=async(retry)=>{const button=$(retry?'#refresh-failed':'#refresh-all');button.disabled=true;try{await post('/api/refresh',{retry});render();toast('공식 자료 확인을 시작했습니다. 다른 화면을 계속 사용할 수 있습니다.');}catch(err){toast(err.message);button.disabled=false;}};
 if($('#refresh-all'))$('#refresh-all').onclick=()=>run(false);
 if($('#refresh-failed'))$('#refresh-failed').onclick=()=>run(true);
 if($('#refresh-status'))$('#refresh-status').onclick=async()=>{try{await load();render();}catch(err){toast(err.message);}};
 if($('#daily-refresh'))$('#daily-refresh').onchange=async ev=>{const enabled=ev.target.checked;ev.target.disabled=true;try{await post('/api/refresh-settings',{enabled,expected_version:refreshState.settings.version});render();toast(enabled?'앱 실행 중 정기 확인을 켰습니다.':'정기 확인을 껐습니다.');}catch(err){ev.target.checked=!enabled;ev.target.disabled=false;toast(err.message);}};
}
setInterval(async()=>{
 if(!['#start','#collection'].includes(location.hash))return;
 try{const res=await fetch('/api/refresh');if(!res.ok)return;const next=await res.json();if(JSON.stringify(next)!==JSON.stringify(refreshState)){await load();render();}}catch{/* Existing status remains visible during a temporary connection failure. */}
},5000);
